                if (!string.IsNullOrEmpty(quoteId) && !isFromLibrary)
                {
                    QuoteDocumentVersionRepository quoteDocumentVersionRepository = new QuoteDocumentVersionRepository(tenant);
                    string documentId = quoteDocumentVersionRepository.GetLastQuoteDocumentVersionDocumentId(quoteId, tenant);
                    DocumentRepository documentRepository = new DocumentRepository(tenant);
                    Document document = documentRepository.GetSingleDocument(tenant, documentId);
                    if (document != null)
                    {
                        IBlobService storageservice = ContainerAccessor.Container.Resolve(typeof(IBlobService), "StorageService", new ParameterOverride("", 1)) as IBlobService;
                        BlobFileInfo fileInfo = new BlobFileInfo()
                        {
                            FileName = document.Id,
                            FolderName = document.Folder,
                            Extension = document.Extension,
                            Tenant = tenant,
                            FileSize = document.FileSize,

                        };

                        result = storageservice.Read(fileInfo);
                    }
                }
                else
                {

                    QuoteTemplateReportHelper quoteTemplateReportHelper = new QuoteTemplateReportHelper();
                    result = quoteTemplateReportHelper.BuildQuoteTemplatePdfReport(quoteId, quoteTemplateId, userId, tenant, null, authToken.Tenant);
                }



                return Request.CreateResponse(HttpStatusCode.OK, result);
            }
            catch (Exception ex)
            {
                return Request.CreateResponse(HttpStatusCode.BadRequest, ApiExceptionBuilder.BuildException(ex));
            }

        }



